import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new ctx.THREE.Group();

  // Load the GLB model (machined rule with jewel)
  ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
    group.add(gltf.scene);
  });

  // Interaction handlers
  const handlers = {
    pointerover: (event) => {
      // Kill any previous hover tween
      if (group.userData._hoverTween) {
        group.userData._hoverTween.kill();
      }
      // Subtle rise-in: translate y by +0.15 scene units
      group.userData._hoverTween = gsap.to(group.position, {
        y: 0.15,
        duration: 0.3,
        ease: 'power3.out',
        overwrite: false,
      });
    },
    pointerout: (event) => {
      // Return to original position
      if (group.userData._hoverTween) {
        group.userData._hoverTween.kill();
      }
      group.userData._hoverTween = gsap.to(group.position, {
        y: 0,
        duration: 0.3,
        ease: 'power3.out',
      });
    },
    click: (event) => {
      ctx.emit('hub-home.select', {});
    },
  };

  // Attach handlers and cleanup
  group.userData.handlers = handlers;
  group.userData.cleanup = () => {
    if (group.userData._hoverTween) {
      group.userData._hoverTween.kill();
    }
    // No additional resources to dispose (GLB is cached internally)
  };

  return group;
}
